    ('sales_fulfillment_request', 'FUL-', 5), ('sales_invoice_request', 'SIR-', 5),
    ('fulfillment_request', 'FUL-', 5), ('invoice_request', 'INV-', 5), ('invoice', 'INV-', 5),
    ('purchase_order', 'PO-', 5), ('purchase_requisition', 'PR-', 6),
