--
-- Name: ensure_organization_subscription(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_organization_subscription() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO organization_subscriptions (
    organization_id, plan_price_id, status, billing_period, current_period_started_at,
    price_snapshot, modules_snapshot, limits_snapshot, included_users_snapshot, metadata
  )
  SELECT
    NEW.id, price.id, 'active', 'monthly', now(),
    jsonb_build_object('plan_code', plan.code, 'plan_name', plan.name, 'amount_paise', price.amount_paise, 'currency', price.currency,
                       'billing_period', price.billing_period, 'version', price.version, 'included_users', price.included_users),
    plan.modules, plan.limits, price.included_users,
    jsonb_build_object('source', 'organizations_ensure_subscription_trigger')
  FROM billing_plans plan
  JOIN billing_plan_prices price ON price.plan_id = plan.id AND price.billing_period = 'monthly' AND price.active
  WHERE plan.code = 'free'
  ON CONFLICT (organization_id) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: guard_billing_price_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_billing_price_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.plan_id IS DISTINCT FROM OLD.plan_id OR NEW.billing_period IS DISTINCT FROM OLD.billing_period
     OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.amount_paise IS DISTINCT FROM OLD.amount_paise
     OR NEW.onboarding_fee_paise IS DISTINCT FROM OLD.onboarding_fee_paise OR NEW.version IS DISTINCT FROM OLD.version
     OR NEW.included_users IS DISTINCT FROM OLD.included_users OR NEW.provider IS DISTINCT FROM OLD.provider THEN
    RAISE EXCEPTION 'billing price version % is immutable; create a new version instead', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.provider_plan_id IS NOT NULL AND NEW.provider_plan_id IS DISTINCT FROM OLD.provider_plan_id THEN
    RAISE EXCEPTION 'billing price version % is permanently linked to its provider plan', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NOT OLD.active AND NEW.active THEN
    RAISE EXCEPTION 'retired billing price version % cannot be reactivated', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: link_billing_price_provider_plan(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_billing_price_provider_plan(p_price_id uuid, p_provider_plan_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  linked text;
BEGIN
  IF p_price_id IS NULL OR p_provider_plan_id IS NULL OR btrim(p_provider_plan_id) = '' OR length(p_provider_plan_id) > 200 THEN
    RAISE EXCEPTION 'link_billing_price_provider_plan needs a price id and a provider plan id' USING ERRCODE = '22023';
  END IF;
  UPDATE public.billing_plan_prices SET provider_plan_id = p_provider_plan_id WHERE id = p_price_id AND provider_plan_id IS NULL;
  SELECT provider_plan_id INTO linked FROM public.billing_plan_prices WHERE id = p_price_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unknown billing price %', p_price_id USING ERRCODE = '22023';
  END IF;
  RETURN linked;
END
$$;


--
-- Name: pending_invitations_for_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_invitations_for_email(p_email text) RETURNS TABLE(id uuid, organization_name text, expires_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT invitation.id, organization.name, invitation.expires_at
    FROM public.organization_invitations invitation
    JOIN public.organizations organization ON organization.id = invitation.organization_id
   WHERE lower(invitation.email) = lower(p_email)
     AND invitation.accepted_at IS NULL AND invitation.revoked_at IS NULL AND invitation.expires_at > now()
   ORDER BY invitation.created_at DESC
   LIMIT 50
$$;


