--

CREATE FUNCTION public.record_billing_audit_event(p_organization_id uuid, p_actor_user_id uuid, p_event_type text, p_entity_id text, p_metadata jsonb, p_before_data jsonb, p_after_data jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
