--
-- Name: revoke_sessions_after_access_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_sessions_after_access_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  affected_user_id uuid;
BEGIN
  affected_user_id := COALESCE(NEW.user_id, OLD.user_id);
  UPDATE sessions
  SET revoked_at = COALESCE(revoked_at, now()),
      revoked_reason = COALESCE(revoked_reason, 'access_changed')
  WHERE user_id = affected_user_id
    AND revoked_at IS NULL;
  RETURN COALESCE(NEW, OLD);
END;
$$;


