--
-- Name: accounting_protect_posted_entry(); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.accounting_protect_posted_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status IN ('posted','reversed') THEN
    IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Posted accounting entries cannot be deleted'; END IF;
    IF NEW.status = OLD.status OR NEW.status NOT IN ('reversed') THEN
      RAISE EXCEPTION 'Posted accounting entries are immutable; create a reversal';
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: accounting_protect_posted_line(); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.accounting_protect_posted_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_status text;
BEGIN
  SELECT status INTO parent_status FROM tenant.accounting_journal_entries WHERE id = OLD.journal_entry_id;
  IF parent_status IN ('posted','reversed') THEN RAISE EXCEPTION 'Lines of a posted accounting entry are immutable'; END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: accounting_protect_posted_subledger_document(); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.accounting_protect_posted_subledger_document() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE old_payload jsonb; new_payload jsonb;
BEGIN
  IF TG_OP='DELETE' AND OLD.status IN ('posted','partially_paid','paid','overdue','disputed','reversed') THEN
    RAISE EXCEPTION 'Posted subledger documents cannot be deleted; create a credit note or reversal';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status IN ('posted','partially_paid','paid','overdue','disputed','reversed') THEN
    old_payload := to_jsonb(OLD) - ARRAY['status','outstanding_amount','e_invoice_status','e_invoice_reference','updated_by','updated_at'];
    new_payload := to_jsonb(NEW) - ARRAY['status','outstanding_amount','e_invoice_status','e_invoice_reference','updated_by','updated_at'];
    IF old_payload IS DISTINCT FROM new_payload THEN
      RAISE EXCEPTION 'Posted subledger document commercial fields are immutable';
    END IF;
  END IF;
  RETURN COALESCE(NEW,OLD);
END;
$$;


--
-- Name: accounting_protect_posted_subledger_line(); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.accounting_protect_posted_subledger_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_status text;
BEGIN
  IF TG_TABLE_NAME='accounting_customer_invoice_lines' THEN
    SELECT status INTO parent_status FROM tenant.accounting_customer_invoices WHERE id=OLD.customer_invoice_id AND organization_id=OLD.organization_id;
  ELSE
    SELECT status INTO parent_status FROM tenant.accounting_vendor_bills WHERE id=OLD.vendor_bill_id AND organization_id=OLD.organization_id;
  END IF;
  IF parent_status IN ('posted','partially_paid','paid','overdue','disputed','reversed') THEN
    RAISE EXCEPTION 'Lines of a posted subledger document are immutable';
  END IF;
  RETURN COALESCE(NEW,OLD);
END;
$$;


--
-- Name: accounting_validate_posted_entry(); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.accounting_validate_posted_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE total_debit numeric(24,6); total_credit numeric(24,6); line_count integer; period_status text;
BEGIN
  IF NEW.status = 'posted' AND OLD.status IS DISTINCT FROM 'posted' THEN
    SELECT count(*), COALESCE(sum(base_debit_amount),0), COALESCE(sum(base_credit_amount),0)
      INTO line_count, total_debit, total_credit
    FROM tenant.accounting_journal_lines
    WHERE journal_entry_id = NEW.id AND organization_id = NEW.organization_id;
    IF line_count < 2 THEN RAISE EXCEPTION 'A posted journal entry requires at least two lines'; END IF;
    IF total_debit <> total_credit THEN RAISE EXCEPTION 'Journal entry is not balanced: debit %, credit %', total_debit, total_credit; END IF;
    SELECT status INTO period_status FROM tenant.fiscal_periods
      WHERE id = NEW.fiscal_period_id AND organization_id = NEW.organization_id;
    IF period_status IS DISTINCT FROM 'open' THEN RAISE EXCEPTION 'Accounting period is not open'; END IF;
    NEW.posted_at = COALESCE(NEW.posted_at, now());
  END IF;
  RETURN NEW;
END;
$$;


