--
-- Name: crm_normalize_comparison_text(text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.crm_normalize_comparison_text(value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT NULLIF(lower(regexp_replace(btrim(COALESCE(value, '')), '[[:space:]]+', ' ', 'g')), '')
$$;


--
-- Name: FUNCTION crm_normalize_comparison_text(value text); Type: COMMENT; Schema: tenant; Owner: -
--

COMMENT ON FUNCTION tenant.crm_normalize_comparison_text(value text) IS 'Canonical F008 case/whitespace comparison normalization; preserves international identity characters.';


