$$;


--
-- Name: crm_normalize_phone(text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.crm_normalize_phone(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT NULLIF(regexp_replace(COALESCE(value, ''), '[^0-9]+', '', 'g'), '')
$$;


