--
-- Name: crm_public_capture_form(text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.crm_public_capture_form(form_key text) RETURNS TABLE(id uuid, organization_id uuid, source_id uuid, campaign_id uuid, owner_user_id uuid, allowed_origins text[], required_fields text[], success_message text, rate_limit_per_hour integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'tenant', 'public', 'pg_temp'
    AS $$
  SELECT
    capture.id,
    capture.organization_id,
    capture.source_id,
    capture.campaign_id,
    capture.owner_user_id,
    capture.allowed_origins,
    capture.required_fields,
    capture.success_message,
    capture.rate_limit_per_hour
  FROM tenant.crm_capture_forms AS capture
  WHERE capture.public_key = form_key
    AND capture.status = 'active'
  LIMIT 1
$$;


--
-- Name: crm_public_marketing_event(text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.crm_public_marketing_event(token text) RETURNS TABLE(organization_id uuid, event_id uuid, name text, starts_at timestamp with time zone, ends_at timestamp with time zone, capacity integer, status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'tenant', 'public'
    AS $$
  SELECT event.organization_id,event.id,event.name,event.starts_at,event.ends_at,event.capacity,event.status
    FROM tenant.crm_marketing_events event
   WHERE event.registration_token=token
     AND event.status IN ('published','live')
   LIMIT 1
$$;


--
-- Name: crm_public_marketing_survey(text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.crm_public_marketing_survey(token text) RETURNS TABLE(organization_id uuid, survey_id uuid, survey_schema jsonb, anonymous_allowed boolean, closes_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'tenant', 'public'
    AS $$
  SELECT survey.organization_id,survey.id,survey.survey_schema,survey.anonymous_allowed,survey.closes_at
    FROM tenant.crm_marketing_surveys survey
   WHERE survey.public_token=token
     AND survey.status='published'
     AND (survey.closes_at IS NULL OR survey.closes_at > now())
   LIMIT 1
$$;


--
-- Name: crm_public_meeting_booking(text); Type: FUNCTION; Schema: tenant; Owner: -
--

CREATE FUNCTION tenant.crm_public_meeting_booking(token text) RETURNS TABLE(organization_id uuid, booking_id uuid, host_user_id uuid, token_type text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'tenant', 'public'
    AS $$
  SELECT booking.organization_id,booking.id,booking.host_user_id,
    CASE WHEN booking.cancellation_token=token THEN 'cancel' ELSE 'reschedule' END
  FROM tenant.crm_meeting_bookings booking
  WHERE booking.status='confirmed'
    AND booking.ends_at > now() - interval '1 day'
    AND (booking.cancellation_token=token OR booking.reschedule_token=token)
  LIMIT 1
$$;


