    activity_type text NOT NULL,
    subject text NOT NULL,
    description text,
    status text DEFAULT 'planned'::text NOT NULL,
    priority text DEFAULT 'medium'::text NOT NULL,
    assigned_to uuid,
    start_at timestamp with time zone,
    due_at timestamp with time zone,
    end_at timestamp with time zone,
    reminder_at timestamp with time zone,
    completed_at timestamp with time zone,
    outcome text,
    location text,
    external_id text,
    recurring_rule text,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    call_direction text,
    call_phone text,
    call_outcome_code text,
    call_started_at timestamp with time zone,
    call_ended_at timestamp with time zone,
    call_duration_seconds integer,
    meeting_location_type text,
    meeting_url text,
    meeting_outcome_code text,
    meeting_started_at timestamp with time zone,
    meeting_ended_at timestamp with time zone,
    meeting_duration_seconds integer,
    meeting_booking_id uuid,
    meeting_calendar_event_id uuid,
    follow_up_reason text,
    follow_up_channel text,
    follow_up_snooze_count integer DEFAULT 0 NOT NULL,
    follow_up_escalate_after_minutes integer,
    follow_up_escalated_at timestamp with time zone,
    follow_up_escalated_to uuid,
    recurrence_config jsonb,
    recurrence_parent_id uuid,
    task_source text DEFAULT 'user_created'::text NOT NULL,
    team_id uuid,
    CONSTRAINT crm_activities_activity_type_check CHECK ((activity_type = ANY (ARRAY['task'::text, 'call'::text, 'meeting'::text, 'email'::text, 'whatsapp'::text, 'sms'::text, 'note'::text, 'follow_up'::text, 'other'::text]))),
    CONSTRAINT crm_activities_call_direction_f013 CHECK (((call_direction IS NULL) OR ((activity_type = 'call'::text) AND (call_direction = ANY (ARRAY['inbound'::text, 'outbound'::text]))))),
    CONSTRAINT crm_activities_call_duration_f013 CHECK (((call_duration_seconds IS NULL) OR ((activity_type = 'call'::text) AND ((call_duration_seconds >= 0) AND (call_duration_seconds <= 86400))))),
    CONSTRAINT crm_activities_call_fields_only_f013 CHECK (((activity_type = 'call'::text) OR ((call_direction IS NULL) AND (call_phone IS NULL) AND (call_outcome_code IS NULL) AND (call_started_at IS NULL) AND (call_ended_at IS NULL) AND (call_duration_seconds IS NULL)))),
    CONSTRAINT crm_activities_call_outcome_f013 CHECK (((call_outcome_code IS NULL) OR ((activity_type = 'call'::text) AND (call_outcome_code = ANY (ARRAY['connected'::text, 'no_answer'::text, 'busy'::text, 'voicemail'::text, 'callback_requested'::text, 'wrong_number'::text, 'failed'::text]))))),
    CONSTRAINT crm_activities_call_time_order_f013 CHECK (((call_started_at IS NULL) OR (call_ended_at IS NULL) OR (call_started_at <= call_ended_at))),
    CONSTRAINT crm_activities_check CHECK (((start_at IS NULL) OR (end_at IS NULL) OR (start_at <= end_at))),
    CONSTRAINT crm_activities_entity_type_check CHECK ((entity_type = ANY (ARRAY['lead'::text, 'opportunity'::text, 'party'::text, 'contact'::text, 'campaign'::text, 'general'::text]))),
    CONSTRAINT crm_activities_follow_up_channel_check CHECK (((follow_up_channel IS NULL) OR (follow_up_channel = ANY (ARRAY['call'::text, 'email'::text, 'meeting'::text, 'whatsapp'::text, 'sms'::text, 'other'::text])))),
    CONSTRAINT crm_activities_follow_up_escalate_minutes_check CHECK (((follow_up_escalate_after_minutes IS NULL) OR ((follow_up_escalate_after_minutes > 0) AND (follow_up_escalate_after_minutes <= 43200)))),
    CONSTRAINT crm_activities_follow_up_scope_check CHECK (((activity_type = 'follow_up'::text) OR ((follow_up_reason IS NULL) AND (follow_up_channel IS NULL) AND (follow_up_snooze_count = 0) AND (follow_up_escalate_after_minutes IS NULL) AND (follow_up_escalated_at IS NULL) AND (follow_up_escalated_to IS NULL)))),
    CONSTRAINT crm_activities_meeting_duration_f014 CHECK (((meeting_duration_seconds IS NULL) OR ((activity_type = 'meeting'::text) AND ((meeting_duration_seconds >= 0) AND (meeting_duration_seconds <= 86400))))),
    CONSTRAINT crm_activities_meeting_fields_only_f014 CHECK (((activity_type = 'meeting'::text) OR ((meeting_location_type IS NULL) AND (meeting_url IS NULL) AND (meeting_outcome_code IS NULL) AND (meeting_started_at IS NULL) AND (meeting_ended_at IS NULL) AND (meeting_duration_seconds IS NULL) AND (meeting_booking_id IS NULL) AND (meeting_calendar_event_id IS NULL)))),
    CONSTRAINT crm_activities_meeting_location_type_f014 CHECK (((meeting_location_type IS NULL) OR ((activity_type = 'meeting'::text) AND (meeting_location_type = ANY (ARRAY['in_person'::text, 'online'::text, 'phone'::text, 'other'::text]))))),
    CONSTRAINT crm_activities_meeting_outcome_f014 CHECK (((meeting_outcome_code IS NULL) OR ((activity_type = 'meeting'::text) AND (meeting_outcome_code = ANY (ARRAY['held'::text, 'no_show'::text]))))),
    CONSTRAINT crm_activities_meeting_time_order_f014 CHECK (((meeting_started_at IS NULL) OR (meeting_ended_at IS NULL) OR (meeting_started_at <= meeting_ended_at))),
    CONSTRAINT crm_activities_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT crm_activities_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text, 'overdue'::text]))),
    CONSTRAINT crm_activities_task_source_check CHECK ((task_source = ANY (ARRAY['user_created'::text, 'lifecycle_generated'::text, 'assignment_generated'::text, 'meeting_generated'::text, 'follow_up_generated'::text, 'recurrence_generated'::text])))
);

